const APP_MODE=window.SALON_MODE||"customer";

const sb=supabase.createClient(SUPABASE_URL,SUPABASE_KEY);
const $=i=>document.getElementById(i),esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fm=n=>Math.round(n).toLocaleString("ar-EG")+" "+C.cfg.currency;
const toast=t=>{const e=document.createElement("div"),x=String(t||""),k=/✓|^تم|تمام|اتحفظ|اتسجل/.test(x)?" ok":/غلط|خطأ|مش |ممنوع|غير مصرح|تعذر|فشل|error|failed|invalid|violat|حد /i.test(x)?" err":"";e.className="toast"+k;e.textContent=x;document.body.appendChild(e);setTimeout(()=>e.remove(),2600)};
(()=>{let n=null;const f=()=>{if(!navigator.onLine){if(!n){n=document.createElement("div");n.className="net";n.setAttribute("role","status");n.textContent="مفيش اتصال بالإنترنت — هنكمل أول ما يرجع";document.body.appendChild(n)}}else if(n){n.remove();n=null}};addEventListener("online",f);addEventListener("offline",f);f()})();
const ST={upcoming:"قادم",checked_in:"وصل",in_service:"على الكرسي",done:"خلص",cancelled:"ملغي",no_show:"لم يحضر"};
let me=null,tab="";const C={cfg:{salon_name:"صالون أبو يوسف",phone:"",address:"",currency:"ج.م",open_hour:10,close_hour:20,slot_minutes:60,days_ahead:5,weekly_off:5,cancel_before_hours:2,points_per_currency:10,max_discount_pct:20,booking_open:true}};

const PD={cashier:{use_attendance:1,use_pos:1,view_stock:1,view_invoices:1,manage_appts:1,view_customers:1,view_customer_phone:1},barber:{use_attendance:1,view_own_sales:1,view_own_commission:1,view_own_finance:1,view_own_reviews:1,view_own_schedule:1},assistant:{use_attendance:1,view_own_finance:1}};
const can=(k,p=me)=>p.role=="owner"||(p.perms&&k in p.perms?!!p.perms[k]:!!(PD[p.role]||{})[k]);
async function loadCfg(){const{data}=await sb.from("app_settings").select("*");(data||[]).forEach(r=>C.cfg[r.key]=r.value);document.title=C.cfg.salon_name;$("brand").innerHTML=ic("menu")+"<span>"+esc(C.cfg.salon_name)+(APP_MODE=="staff"?" · الموظفين":"")+"</span>"}
async function boot(){
await loadCfg();
const{data:{session}}=await sb.auth.getSession();
if(!session){let cr=null;try{cr=JSON.parse(localStorage.getItem("salon_cred"))}catch(e){}
if(cr&&APP_MODE=="customer"){const r=await sb.auth.signInWithPassword({email:cr.e,password:cr.p});if(!r.error)return boot()}
return authView()}
const{data:p}=await sb.from("profiles").select("*").eq("id",session.user.id).single();
me=p||{role:"customer",full_name:session.user.email,id:session.user.id};
const staff=["owner","cashier","barber","assistant"].includes(me.role);
if(APP_MODE=="customer"&&staff)return wrongPage("staff");if(APP_MODE=="staff"&&!staff)return wrongPage("customer");
const own=me.role=="owner";
if(staff){const T=[];if(can("use_pos"))T.push(["pos","الكاشير"]);if(can("use_pos"))T.push(["cash","الخزنة"]);if(can("manage_appts"))T.push(["appts","الحجوزات"]);if(can("view_stock"))T.push(["stock","المخزون"]);if(can("view_invoices"))T.push(["inv","الفواتير"]);if(can("view_customers"))T.push(["cust","العملاء"]);if(can("view_reports"))T.push(["rep","التقارير"]);if(me.role=="barber"||me.role=="assistant"||can("use_attendance"))T.push(["me","شاشتي"]);if(own)T.push(["svc","الخدمات"],["fin","المالية"],["team","الموظفين"],["set","الإعدادات"]);C.tabs=[...T,["out","خروج"]];go(T[0]?T[0][0]:"none")}
else{const{data:cu}=await sb.from("customers").select("id").eq("user_id",session.user.id).maybeSingle();if(!cu)return authView("c");C.tabs=[["book","احجز"],["queue","دوري"],["mine","حجوزاتي"],["loy","نقاطي"],["menu","المنيو"]];go("book")}}

function go(t){clearInterval(C.poll);if(t=="out"){sb.auth.signOut().then(()=>{$("nav").innerHTML="";authView()});return}
tab=t;$("app").classList.remove("still");const NV=C.tabs.length>5?4:C.tabs.length;$("nav").className="";$("nav").innerHTML=(C.tabs.length>NV?"<i class=\"brk\"></i>":"")+C.tabs.map((x,i)=>`<button class="${(x[0]==t?"on":"")+(i>=NV?" x":"")}" onclick="go('${x[0]}')">${ic(x[0])}<span>${x[1]}</span></button>`).join("")+(C.tabs.length>NV?`<button class="more${C.tabs.slice(NV).some(x=>x[0]==t)?" on":""}" aria-label="المزيد" onclick="event.stopPropagation();$('nav').classList.toggle('open')">${ic("dot3")}<span>المزيد</span></button>`:"");put(SK);scrollTo(0,0);V[t]()}
const put=h=>{$("app").innerHTML=h;polish()};
function polish(){const A=$("app");A.querySelectorAll(".tag").forEach(t=>{const k=Object.keys(ST).find(x=>ST[x]==t.textContent.trim());if(k)t.classList.add("st-"+k)});A.querySelectorAll(":scope>p.m").forEach(p=>{if(/^(مفيش|لسه|لا يوجد|ما فيش)/.test(p.textContent.trim()))p.classList.add("empty")})}

function authView(){put(`<h1>أهلاً بيك في ${esc(C.cfg.salon_name)}</h1><div class="box"><input id="nm" placeholder="الاسم (للتسجيل الجديد فقط)"><input id="em" type="email" placeholder="البريد الإلكتروني"><input id="pw" type="password" placeholder="كلمة السر (6 حروف على الأقل)"><div class="chips"><button class="btn" onclick="login()">دخول</button><button class="btn g" onclick="signup()">حساب جديد</button></div></div>`)}
async function login(){const{error}=await sb.auth.signInWithPassword({email:$("em").value.trim(),password:$("pw").value});error?toast("بيانات الدخول غلط"):boot()}
async function signup(){const{error}=await sb.auth.signUp({email:$("em").value.trim(),password:$("pw").value,options:{data:{full_name:$("nm").value.trim()}}});if(error)return toast(error.message);toast("تم إنشاء الحساب");boot()}

const V={
// ===== عميل =====
async book(){
if(!C.cfg.booking_open)return put(`<h1>الحجز</h1><p class="m">الحجز أونلاين متوقف حاليًا. كلمنا على ${esc(C.cfg.phone||"الصالون")}.</p>`);
const[{data:sv},{data:br}]=await Promise.all([sb.from("services").select("*").eq("active",true).order("id"),sb.rpc("list_barbers")]);
C.sv=sv||[];C.br=br||[];C.b={s:[],barber:null,day:0,time:null};drawBook()},
async mine(){
const{data}=await sb.from("appointments").select("id,starts_at,status,appointment_services(services(name)),reviews:invoices(id,reviews(rating))").order("starts_at",{ascending:false});
put(`<h1>حجوزاتي</h1>`+(data?.length?data.map(a=>{const inv=a.reviews?.[0],rated=inv?.reviews?.length;return `<div class="row"><div><b>${new Date(a.starts_at).toLocaleString("ar-EG",{weekday:"long",hour:"2-digit",minute:"2-digit",day:"numeric",month:"numeric"})}</b><div class="m">${(a.appointment_services||[]).map(x=>x.services.name).join(" + ")}</div></div><div><span class="tag">${ST[a.status]}</span>${a.status=="done"&&inv&&!rated?`<br><button class="btn s" onclick="rateView(${inv.id})">قيّم</button>`:""}${rated?`<div class="m">★ ${inv.reviews[0].rating}</div>`:""}${a.status=="upcoming"?`<br><button class="btn s g" onclick="cancelA(${a.id})">إلغاء</button>`:""}</div></div>`}).join(""):`<p class="m">لسه معندكش حجوزات.</p>`))},
// ===== موظفين =====
async pos(){
const[{data:sv},{data:pr},{data:cu},{data:br},{data:asx}]=await Promise.all([sb.from("services").select("*").eq("active",true),sb.from("products").select("*").eq("active",true),sb.from("customers").select("id,name"),sb.from("profiles").select("id,full_name").eq("role","barber"),sb.from("profiles").select("id,full_name,commission_pct").eq("role","assistant")]);
C.P={sv,pr,cu,br,as:asx||[],sa:C.P?.sa||{},s:C.P?.s||[],p:C.P?.p||[],cid:C.P?.cid||"",bid:C.P?.bid||"",appt:C.P?.appt||null,disc:0,pay:"cash"};drawPos();if(C.P.cid)loadV()},
async appts(){
const from=new Date();from.setHours(0,0,0,0);
const{data}=await sb.from("appointments").select("id,starts_at,status,customer_id,barber_id,customers(name),profiles(full_name),appointment_services(service_id,services(name))").gte("starts_at",from.toISOString()).order("starts_at");
C.A=data||[];put(`<h1>الحجوزات</h1>`+(C.A.length?C.A.map(a=>`<div class="row"><div><b>${new Date(a.starts_at).toLocaleString("ar-EG",{weekday:"short",hour:"2-digit",minute:"2-digit"})}</b> · ${esc(a.customers?.name)}<div class="m">${a.appointment_services.map(x=>esc(x.services.name)).join(" + ")} · ${esc(a.profiles?.full_name||"أي حلاق")}</div></div><div style="text-align:left"><span class="tag">${ST[a.status]}</span><br>${a.status=="upcoming"?`<button class="btn s" onclick="setS(${a.id},'checked_in')">وصل</button> <button class="btn s g" onclick="setS(${a.id},'cancelled')">إلغاء</button>`:""}${a.status=="checked_in"?`<button class="btn s" onclick="setS(${a.id},'in_service')">ابدأ</button>`:""}${a.status=="in_service"?`<button class="btn s" onclick="payAppt(${a.id})">دفع</button>`:""}</div></div>`).join(""):`<p class="m">مفيش حجوزات قادمة.</p>`))},
async stock(){
const{data}=await sb.from("products").select("*").order("name");
put(`<h1>المخزون</h1>`+data.map(p=>`<div class="row"><div><b>${esc(p.name)}</b><div class="m">شراء ${p.cost} · بيع ${p.price}</div></div><div style="text-align:left"><span class="tag" style="${p.stock<=p.min_stock?"background:var(--red);color:#fff":""}">${p.stock} قطعة</span><br>${can("restock")?`<button class="btn s g" onclick="restock(${p.id},${p.stock})">+10 توريد</button>`:""}</div></div>`).join(""))},
async inv(){
const{data,error}=await sb.from("invoices").select("no,total,payment_method,created_at,customers(name),invoice_items(name,qty,unit_price)").order("created_at",{ascending:false}).limit(50);
if(error)return put(`<h1>الفواتير</h1><p class="m">مفيش صلاحية لعرض الفواتير لحسابك.</p>`);
put(`<h1>الفواتير</h1>`+(data.length?data.map(i=>`<details class="row" style="display:block"><summary><b>#${i.no}</b> · ${esc(i.customers?.name||"عميل عابر")} · <b>${fm(i.total)}</b></summary>${i.invoice_items.map(x=>`<div class="tot m"><span>${esc(x.name)} ×${x.qty}</span><span>${fm(x.unit_price*x.qty)}</span></div>`).join("")}<div class="m">${new Date(i.created_at).toLocaleString("ar-EG")} · ${i.payment_method}</div></details>`).join(""):`<p class="m">لسه مفيش فواتير.</p>`))}
};

function drawBook(){const b=C.b,days=[...Array(+C.cfg.days_ahead)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()+i);return{i,off:d.getDay()==C.cfg.weekly_off,l:i?d.toLocaleDateString("ar-EG",{weekday:"short",day:"numeric",month:"numeric"}):"اليوم"}});
const times=slots();
put(`<h1>احجز موعد</h1><h2>الخدمات</h2><div class="chips">${C.sv.map(s=>`<button class="chip ${b.s.includes(s.id)?"sel":""}" onclick="tgS(${s.id})">${esc(s.name)} · ${s.price}</button>`).join("")}</div>
<h2>الحلاق</h2><div class="chips"><button class="chip ${b.barber===null?"sel":""}" onclick="C.b.barber=null;bookSlots()">أي حلاق</button>${C.br.map(x=>`<button class="chip ${b.barber===x.id?"sel":""}" onclick="C.b.barber='${x.id}';bookSlots()">${esc(x.full_name)}</button>`).join("")}</div>
<h2>اليوم</h2><div class="chips">${days.map(d=>`<button class="chip ${b.day==d.i?"sel":""}" ${d.off?"disabled":""} onclick="C.b.day=${d.i};C.b.time=null;bookSlots()">${d.l}</button>`).join("")}</div>
<h2>الساعة</h2><div class="chips" id="slots"></div>
<button class="btn" style="width:100%;margin-top:10px" ${b.s.length&&b.time!=null?"":"disabled"} onclick="confirmBook()">تأكيد الحجز · ${fm(C.sv.filter(s=>b.s.includes(s.id)).reduce((a,s)=>a+s.price,0))}</button>`);
bookSlots()}
async function bookSlots(){const b=C.b;const d=new Date();d.setDate(d.getDate()+b.day);const ds=d.toISOString().slice(0,10);
const[{data},{data:bh}]=await Promise.all([sb.rpc("taken_slots",{p_day:ds}),sb.rpc("barber_hours",{p_day:ds})]);const times=slots();const okB=(bid,t)=>{const h=(bh||[]).find(x=>x.barber_id==bid);return !h||(!h.is_off&&t+":00">=h.start_time&&t+":00"<h.end_time)};
const mk=t=>{const x=new Date(d);const[h,m]=t.split(":");x.setHours(+h,+m,0,0);return x};
const taken=t=>{const iso=mk(t).getTime(),bt=r=>new Date(r.starts_at).getTime()==iso;if(b.barber)return !okB(b.barber,t)||(data||[]).some(r=>bt(r)&&r.barber_id==b.barber);return C.br.length>0&&!C.br.some(x=>okB(x.id,t)&&!(data||[]).some(r=>bt(r)&&r.barber_id==x.id))};
const past=t=>mk(t)<new Date();
if($("slots"))$("slots").innerHTML=times.map(t=>`<button class="chip ${b.time===t?"sel":""}" ${taken(t)||past(t)?"disabled":""} onclick="C.b.time='${t}';drawBook()">${t}</button>`).join("");
document.querySelector(".btn[onclick='confirmBook()']")&&(document.querySelector(".btn[onclick='confirmBook()']").disabled=!(b.s.length&&b.time))}
function tgS(id){const b=C.b;b.s=b.s.includes(id)?b.s.filter(x=>x!=id):[...b.s,id];drawBook()}
async function confirmBook(){const b=C.b;const{data:{user}}=await sb.auth.getUser();
let{data:cu}=await sb.from("customers").select("id").eq("user_id",user.id).maybeSingle();
if(!cu){const r=await sb.from("customers").insert({user_id:user.id,name:me.full_name}).select("id").single();cu=r.data}
const d=new Date();d.setDate(d.getDate()+b.day);const[h,m]=b.time.split(":");d.setHours(+h,+m,0,0);
const{data:a,error}=await sb.from("appointments").insert({customer_id:cu.id,barber_id:b.barber,starts_at:d.toISOString()}).select("id").single();
if(error)return toast(error.code=="23505"?"الميعاد ده اتحجز، اختار وقت تاني":error.message);
await sb.from("appointment_services").insert(b.s.map(s=>({appointment_id:a.id,service_id:s})));
toast("تم تأكيد حجزك ✓");go("mine")}
async function cancelA(id){const{error}=await sb.rpc("cancel_my_appt",{p_id:id});error?toast(error.message):go("mine")}
const slots=()=>{const o=[],st=+C.cfg.slot_minutes;for(let m=C.cfg.open_hour*60;m+st<=C.cfg.close_hour*60;m+=st)o.push(String(m/60|0).padStart(2,"0")+":"+String(m%60).padStart(2,"0"));return o};
function rateView(inv){C.R={inv,r:0,tg:[]};drawRate()}
function drawRate(){const R=C.R,tags=["نظافة المكان","دقة الموعد","مهارة الحلاق","سعر مناسب"];
put(`<h1>قيّم تجربتك</h1><div class="stars" style="text-align:center">${[1,2,3,4,5].map(i=>`<button class="${R.r>=i?"on":""}" aria-label="${i}" onclick="C.R.r=${i};drawRate()">★</button>`).join("")}</div><div class="chips">${tags.map(t=>`<button class="chip ${R.tg.includes(t)?"sel":""}" onclick="C.R.tg=C.R.tg.includes('${t}')?C.R.tg.filter(x=>x!='${t}'):[...C.R.tg,'${t}'];drawRate()">${t}</button>`).join("")}</div><input id="nt" placeholder="ملاحظات (اختياري)"><button class="btn" ${R.r?"":"disabled"} onclick="sendRate()">إرسال</button>`)}
async function sendRate(){const R=C.R;const{data:{user}}=await sb.auth.getUser();
const{data:cu}=await sb.from("customers").select("id").eq("user_id",user.id).single();
const{data:inv}=await sb.from("invoices").select("barber_id").eq("id",R.inv).single();
const{error}=await sb.from("reviews").insert({invoice_id:R.inv,customer_id:cu.id,barber_id:inv?.barber_id,rating:R.r,tags:R.tg,note:$("nt").value});
error?toast(error.message):(toast("شكرًا على تقييمك 💈"),go("mine"))}

// ===== كاشير =====
function drawPos(){const P=C.P,sub=P.s.reduce((a,i)=>a+P.sv.find(x=>x.id==i).price,0)+P.p.reduce((a,i)=>a+P.pr.find(x=>x.id==i.id).price*i.q,0),d=sub*P.disc/100;
put(`<h1>الكاشير</h1><h2>الخدمات</h2><div class="chips">${P.sv.map(x=>`<button class="chip ${P.s.includes(x.id)?"sel":""}" onclick="P_s(${x.id})">${esc(x.name)} · ${x.price}</button>`).join("")}</div><h2>المنتجات</h2><div class="chips">${P.pr.map(x=>{const c=P.p.find(y=>y.id==x.id);return `<button class="chip ${c?"sel":""}" ${x.stock<=0?"disabled":""} onclick="P_p(${x.id})">${esc(x.name)} · ${x.price}${c?" ×"+c.q:""}</button>`}).join("")}</div>
<div class="box" style="margin-top:12px"><select onchange="C.P.cid=this.value;loadV()"><option value="">عميل عابر</option>${P.cu.map(c=>`<option value="${c.id}" ${P.cid==c.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select>${P.vs?.length?`<select onchange="C.P.rid=this.value"><option value="">بدون كوبون ولاء</option>${P.vs.map(v=>`<option value="${v.id}" ${P.rid==v.id?"selected":""}>${esc(v.loyalty_rewards.name)} (${v.code})</option>`).join("")}</select>`:""}<select onchange="C.P.bid=this.value"><option value="">اختار الحلاق</option>${P.br.map(c=>`<option value="${c.id}" ${P.bid==c.id?"selected":""}>${esc(c.full_name)}</option>`).join("")}</select>
<div class="chips">${[0,5,10,20].filter(x=>me.role=="owner"||x<=C.cfg.max_discount_pct).map(x=>`<button class="chip ${P.disc==x?"sel":""}" onclick="C.P.disc=${x};drawPos()">خصم ${x}%</button>`).join("")}${[["cash","كاش"],["card","كارت"],["wallet","محفظة"]].map(x=>`<button class="chip ${P.pay==x[0]?"sel":""}" onclick="C.P.pay='${x[0]}';drawPos()">${x[1]}</button>`).join("")}</div>
${P.as.length&&P.s.length?`<h2>المساعد (اختياري)</h2><div class="box">${P.s.map(id=>{const v=P.sv.find(x=>x.id==id);return `<div class="m" style="margin-top:6px">${esc(v.name)}</div><select onchange="P_a(${id},this.value)"><option value="">بدون مساعد</option>${P.as.map(a=>`<option value="${a.id}" ${P.sa[id]==a.id?"selected":""}>${esc(a.full_name)} (${+a.commission_pct}%)</option>`).join("")}</select>`}).join("")}</div>`:""}
<div class="tot f"><span>المطلوب</span><span>${fm(sub-d)}</span></div><button class="btn" style="width:100%;margin-top:8px" ${sub?"":"disabled"} onclick="checkout()">دفع وإصدار فاتورة</button></div>`)}
function P_s(id){const P=C.P;if(P.s.includes(id))delete P.sa[id];P.s=P.s.includes(id)?P.s.filter(x=>x!=id):[...P.s,id];drawPos()}
function P_a(id,v){if(v)C.P.sa[id]=v;else delete C.P.sa[id]}
function P_p(id){const P=C.P,c=P.p.find(x=>x.id==id),pr=P.pr.find(x=>x.id==id);if(c){c.q<pr.stock?c.q++:toast("الكمية خلصت")}else P.p.push({id,q:1});drawPos()}
async function checkout(){const P=C.P;if(Object.keys(P.sa||{}).length&&!P.bid)return toast("اختار الحلاق الأول قبل ما تحدد مساعد");
const items=[...P.s.map(id=>({type:"service",id,qty:1,assistant:(P.sa||{})[id]||null})),...P.p.map(x=>({type:"product",id:x.id,qty:x.q}))];
const{data,error}=await sb.rpc("checkout_invoice",{p_customer:P.cid?+P.cid:null,p_barber:P.bid||null,p_items:items,p_discount_pct:P.disc,p_method:P.pay,p_appointment:P.appt,p_redemption:P.rid?+P.rid:null});
if(error)return toast(error.message);C.P=null;toast("تم إصدار فاتورة رقم "+data);go("inv")}
async function setS(id,s){await sb.from("appointments").update({status:s}).eq("id",id);go("appts")}
function payAppt(id){const a=C.A.find(x=>x.id==id);C.P={s:a.appointment_services.map(x=>x.service_id),p:[],cid:a.customer_id,bid:a.barber_id||"",appt:id};go("pos")}
async function restock(id,q){const{error}=await sb.rpc("restock_product",{p_id:id,p_qty:10});error?toast(error.message):go("stock")}
// ===== شاشة الموظف والإدارة =====
const mm=x=>x==null?"—":fm(x);const KIND={advance:"سحب",deduction:"خصم",bonus:"مكافأة"};C.rg="month";
const rangeOf=k=>{const a=new Date();a.setHours(0,0,0,0);const b=new Date(a);
if(k=="week"){a.setDate(a.getDate()-((a.getDay()+1)%7));b.setTime(a.getTime());b.setDate(b.getDate()+7)}
else if(k=="month"){a.setDate(1);b.setTime(a.getTime());b.setMonth(b.getMonth()+1)}else b.setDate(b.getDate()+1);
return[a.toISOString(),b.toISOString()]};
async function panel(id,owner){
C.reload=()=>panel(id,owner);const[f,t]=rangeOf(C.rg);
const[{data:sm,error:e1},{data:al},{data:tx},{data:rv},{data:sc},{data:at},{data:op},{data:sh},{data:lv}]=await Promise.all([
sb.rpc("staff_summary",{p_staff:id,p_from:f,p_to:t}),
sb.rpc("assist_log",{p_staff:id,p_from:f,p_to:t}),
sb.from("staff_transactions").select("*").eq("staff_id",id).gte("created_at",f).lt("created_at",t).order("created_at",{ascending:false}),
sb.from("reviews").select("rating,tags,note,created_at").eq("barber_id",id).order("created_at",{ascending:false}).limit(20),
sb.rpc("staff_schedule",{p_staff:id}),sb.from("attendance").select("*").eq("staff_id",id).gte("check_in",f).lt("check_in",t).order("check_in",{ascending:false}),sb.from("attendance").select("id,check_in").eq("staff_id",id).is("check_out",null).limit(1),sb.from("staff_shifts").select("*").eq("staff_id",id),sb.from("staff_leaves").select("*").eq("staff_id",id).gte("to_date",new Date().toISOString().slice(0,10)).order("from_date")]);
if(e1)return $("panel").innerHTML=`<p class="m">${esc(e1.message)}</p>`;
const s=sm?.[0]||{},avg=rv?.length?(rv.reduce((a,r)=>a+r.rating,0)/rv.length).toFixed(1):"-";
const S=owner?{f:1,s:1,r:1}:{f:can("view_own_finance"),s:can("view_own_schedule"),r:can("view_own_reviews")};const card=(l,v,c)=>`<div class="box kpi"><div class="kpi-l">${l}</div><div class="kpi-v" style="color:${c||"inherit"}">${v}</div></div>`;
const hm=d=>new Date(d).toLocaleTimeString("ar-EG",{hour:"2-digit",minute:"2-digit"}),DN=["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"];
const attOn=owner||can("use_attendance");
const attBox=!owner&&can("use_attendance")?`<div class="box" style="margin:10px 0;text-align:center">${op?.length?`<div class="m">حاضر من ${hm(op[0].check_in)}</div><button class="btn" style="width:100%" onclick="att('check_out')">تسجيل انصراف</button>`:`<button class="btn" style="width:100%;background:var(--ok)" onclick="att('check_in')">تسجيل حضور</button>`}</div>`:"";
const hrs=(at||[]).reduce((a,r)=>a+((r.check_out?new Date(r.check_out):new Date())-new Date(r.check_in))/36e5,0),late=(at||[]).reduce((a,r)=>a+r.late_min,0);
const attHist=attOn?`<h2>الحضور والانصراف</h2><div class="m" style="margin-bottom:6px">${(at||[]).length} يوم · ${hrs.toFixed(1)} ساعة · تأخير ${late} دقيقة</div>${(at||[]).map(r=>`<div class="row"><div><b>${new Date(r.check_in).toLocaleDateString("ar-EG",{weekday:"short",day:"numeric",month:"numeric"})}</b><div class="m">${hm(r.check_in)} ← ${r.check_out?hm(r.check_out):"لسه حاضر"}</div></div><div style="text-align:left">${r.late_min?`<span class="tag" style="background:var(--red);color:#fff">متأخر ${r.late_min} د</span>`:`<span class="tag">في الميعاد</span>`}${r.note?`<div class="m">${esc(r.note)}</div>`:""}</div></div>`).join("")}`:"";
const shBox=`<h2>جدول شغلي</h2>${sh?.length?[0,1,2,3,4,5,6].map(d=>{const x=sh.find(y=>y.weekday==d);return x?`<div class="row"><b>${DN[d]}</b><span>${x.is_off?"إجازة":x.start_time.slice(0,5)+" ← "+x.end_time.slice(0,5)}</span></div>`:""}).join(""):`<p class="m">لسه مفيش شيفت محدد.</p>`}${lv?.length?`<div class="m">إجازات جاية:</div>`+lv.map(l=>`<div class="row"><span>${l.from_date} ← ${l.to_date}</span><span class="m">${esc(l.reason||"")}</span></div>`).join(""):""}`;
$("panel").innerHTML=`${attBox}<div class="chips">${[["day","اليوم"],["week","الأسبوع"],["month","الشهر"]].map(x=>`<button class="chip ${C.rg==x[0]?"sel":""}" onclick="C.rg='${x[0]}';C.reload()">${x[1]}</button>`).join("")}</div>
<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">${s.who=="assistant"?card("راتب الفترة",mm(s.salary),"var(--ok)")+card("خدمات شاركت فيها",s.assisted??0):card("مبيعاتي"+(s.cuts==null?"":" ("+s.cuts+" زبون)"),mm(s.sales))+card("عمولتي",mm(s.commission),"var(--ok)")+(s.assistant_cuts==null?"":card("خصم مساعد",mm(s.assistant_cuts),"var(--red)"))+(+s.salary>0?card("راتب ثابت",mm(s.salary),"var(--ok)"):"")}${card("مكافآت",mm(s.bonuses),"var(--ok)")}${card("سحب",mm(s.advances),"var(--red)")}${card("خصومات",mm(s.deductions),"var(--red)")}${card("الصافي المستحق",mm(s.net),"var(--brass)")}</div>
${owner?`<h2>تسجيل حركة</h2><div class="box"><select id="tk">${Object.entries(KIND).map(k=>`<option value="${k[0]}">${k[1]}</option>`).join("")}</select><input id="ta" type="number" inputmode="decimal" placeholder="المبلغ"><input id="tn" placeholder="ملاحظة (اختياري)"><button class="btn" onclick="addTx('${id}')">حفظ الحركة</button></div>`:""}
${al?.length?`<h2>${s.who=="assistant"?"الخدمات اللي شاركت فيها":"خصم المساعدين على خدماتك"}</h2>`+al.map(x=>`<div class="row"><div><b>#${x.inv_no}</b> · ${esc(x.service_name)} · ${fm(x.price)}<div class="m">${new Date(x.created).toLocaleDateString("ar-EG")} · ${s.who=="assistant"?"مع الحلاق "+esc(x.barber_name||"—"):"اتخصم للمساعد "+esc(x.assistant_name)}</div></div>${s.who=="assistant"?"":`<b style="color:var(--red)">- ${fm(x.cut)}</b>`}</div>`).join(""):""}
<h2 ${S.f?"":"hidden"}>الحركات</h2>${tx?.length?tx.map(x=>`<div class="row"><div><b style="color:${x.kind=="bonus"?"var(--ok)":"var(--red)"}">${KIND[x.kind]}</b> · ${fm(x.amount)}<div class="m">${new Date(x.created_at).toLocaleDateString("ar-EG")} ${esc(x.note||"")}</div></div>${owner?`<button class="btn s g" onclick="delTx(${x.id})">حذف</button>`:""}</div>`).join(""):`<p class="m" ${S.f?"":"hidden"}>مفيش حركات في الفترة دي.</p>`}
<h2 ${S.s?"":"hidden"}>دور زباينك (اليوم والجاي)</h2>${sc?.length?sc.map(a=>`<div class="row"><div><b>#${a.ticket_no}</b> · ${esc(a.customer_name)}${a.customer_phone?" · "+esc(a.customer_phone):""}<div class="m">${a.day} · ${PLB[a.period]} · ${esc(a.services)} · ${fm(a.total)}</div></div><div style="text-align:left"><span class="tag">${a.finished?"خلصت":a.called&&a.status=="upcoming"?"مستدعى"+(a.eta=="on_way"?" (في الطريق)":""):ST[a.status]}</span>${!owner?`<br>${a.status!="in_service"&&!a.called?`<button class="btn s" onclick="tk('call_ticket',${a.id})">استدعاء</button> `:""}${a.status!="in_service"?`<button class="btn s g" onclick="myS(${a.id},'in_service')">ابدأ</button>`:!a.finished?`<button class="btn s" onclick="tk('finish_ticket',${a.id})">خلصت</button>`:""}`:""}</div></div>`).join(""):`<p class="m" ${S.s?"":"hidden"}>مفيش زباين محجوزة.</p>`}
${attHist}${attOn?shBox:""}<h2 ${S.r?"":"hidden"}>تقييماتي (المتوسط ★ ${avg})</h2>${rv?.length?rv.map(r=>`<div class="row" style="display:block"><b style="color:var(--brass)">${"★".repeat(r.rating)}</b> <span class="m">${(r.tags||[]).map(esc).join(" · ")}</span>${r.note?`<div>${esc(r.note)}</div>`:""}</div>`).join(""):`<p class="m" ${S.r?"":"hidden"}>لسه مفيش تقييمات.</p>`}`}
async function addTx(id){const a=+$("ta").value;if(!(a>0))return toast("اكتب مبلغ صحيح");
const{error}=await sb.from("staff_transactions").insert({staff_id:id,kind:$("tk").value,amount:a,note:$("tn").value});error?toast(error.message):(toast("تم الحفظ"),C.reload())}
