book:[["booking_open","الحجز أونلاين شغّال","bool"],["days_ahead","الحجز قبلها بكام يوم","number"],["weekly_off","يوم الإجازة الأسبوعي","day"],["max_queue_per_period","أقصى زباين في الفترة لكل حلاق","number"],["max_daily_bookings","أقصى حجوزات في اليوم (0 = بلا حد)","number"],["max_active_per_customer","أقصى حجوزات نشطة للعميل (0 = بلا حد)","number"],["no_show_after_minutes","مهلة عدم الحضور بعد النداء بالدقايق (0 = مقفول)","number"],["near_turn_threshold","نبّه العميل لما يبقى قدامه كام واحد","number"],["smart_assignment_enabled","توزيع تلقائي على أقل حلاق زحمة (لو العميل ما اختارش حلاق)","bool"],["show_queue_number","إظهار رقم الدور للعميل","bool"],["show_people_ahead","إظهار عدد اللي قدامه","bool"],["show_estimated_wait","إظهار وقت الانتظار المتوقع","bool"]],
